scripts.continued_fraction_numerator:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Initialize
    p_minus_1 = 1
    p_0 = terms[0]

    # If there's only one term, return it
    if len(terms) == 1:
        return float(p_0)

    # Compute subsequent numerators
    p_prev_prev = p_minus_1
    p_prev = p_0

    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev + p_prev_prev
        p_prev_prev = p_prev
        p_prev = p_curr

    return float(p_prev)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])

    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

